 getSpeakerMappings(meetingId:string):SpeakerMapping[]{const rows=this.db.prepare('SELECT speaker_id,member_id FROM meeting_speaker_mappings WHERE meeting_id=? ORDER BY speaker_id').all(meetingId) as Row[];return rows.map(r=>({speakerId:r.speaker_id,memberId:r.member_id}))}
 setSpeakerMapping(meetingId:string,speakerId:string,memberId:string|null):SpeakerMapping[]{
  if(!speakerId||!speakerId.trim())throw new Error('Speaker ID is required.');
  const meetingRow=this.db.prepare('SELECT project_snapshot_json,project_id FROM meetings WHERE id=?').get(meetingId) as Row|undefined;
  if(!meetingRow)throw new Error('Meeting not found.');
  if(memberId){
   const snapshot=json<ProjectSnapshot|null>(meetingRow.project_snapshot_json,null);
   let member = (snapshot?.members?.find(m=>m.id===memberId) as { id: string; name: string } | undefined);
   if(!member&&meetingRow.project_id){
    member = this.db.prepare('SELECT id,name FROM project_members WHERE project_id=? AND id=?').get(meetingRow.project_id,memberId) as { id: string; name: string } | undefined;
   }
   if(!member)throw new Error('Selected member does not belong to this project.');
   this.db.prepare('INSERT INTO meeting_speaker_mappings(id,meeting_id,speaker_id,member_id,created_at,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(meeting_id,speaker_id) DO UPDATE SET member_id=excluded.member_id,updated_at=excluded.updated_at').run(randomUUID(),meetingId,speakerId,memberId,now(),now());
   const displayName=`${member.name} (${speakerId})`;
   this.db.prepare('UPDATE transcript_segments SET speaker=? WHERE meeting_id=? AND (speaker_id=? OR speaker=?)').run(displayName,meetingId,speakerId,speakerId);
  }else{
   this.db.prepare('DELETE FROM meeting_speaker_mappings WHERE meeting_id=? AND speaker_id=?').run(meetingId,speakerId);
   this.db.prepare('UPDATE transcript_segments SET speaker=? WHERE meeting_id=? AND speaker_id=?').run(speakerId,meetingId,speakerId);
  }
  const allMappings=this.getSpeakerMappings(meetingId);
  const mappingsObj:Record<string,string>={};
  for(const m of allMappings)mappingsObj[m.speakerId]=m.memberId;
  this.db.prepare('UPDATE meetings SET speaker_mappings_json=?,updated_at=? WHERE id=?').run(JSON.stringify(mappingsObj),now(),meetingId);
  return allMappings;
 }
