export function parseTranscript(transcript:string,meetingId:string):TranscriptSegment[]{const segments=transcript.split(/\n+/).map(line=>line.trim()).filter(Boolean).map((line,sequence)=>{const timed=line.match(/^\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\]\s*(.*)$/);const text=timed?timed[4]:line;const speakerMatch=text.match(/^([^:]{1,80}):\s*(.*)$/);const rawSpeaker=speakerMatch?.[1]?.trim()||null;let speakerId:string|null=null;if(rawSpeaker){const anonMatch=rawSpeaker.match(/\b(SPEAKER_\d+)\b/i);if(anonMatch)speakerId=anonMatch[1].toUpperCase()}const startMs=timed?(Number(timed[1])*60+Number(timed[2]))*1000+Number((timed[3]||'0').padEnd(3,'0')):null;return{id:randomUUID(),meetingId,sequence,startMs,endMs:null as number|null,start:startMs!==null?startMs/1000:null,end:null as number|null,speaker:rawSpeaker,speakerId,speakerConfidence:speakerId?0.9:null,text:speakerMatch?.[2]?.trim()||text}});return segments.map((segment,index)=>{const next=segments[index+1];const endMs=segment.startMs!==null&&next?.startMs!==null&&next?.startMs!==undefined&&next.startMs>segment.startMs?next.startMs:null;return{...segment,endMs,end:endMs!==null?endMs/1000:null}})}
function countChunks(text:string){return text.split(/\n(?=#{1,6}\s)|\n\s*\n/).filter(x=>x.trim()).length}
