const SCHEMA=`
CREATE TABLE IF NOT EXISTS storage_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',instructions TEXT NOT NULL DEFAULT '',glossary_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS task_types(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',position INTEGER NOT NULL DEFAULT 0,UNIQUE(project_id,name COLLATE NOCASE));
CREATE TABLE IF NOT EXISTS product_surfaces(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',position INTEGER NOT NULL DEFAULT 0,UNIQUE(project_id,name COLLATE NOCASE));
CREATE TABLE IF NOT EXISTS surface_components(id TEXT PRIMARY KEY,surface_id TEXT NOT NULL REFERENCES product_surfaces(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',UNIQUE(surface_id,name COLLATE NOCASE));
CREATE TABLE IF NOT EXISTS work_areas(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',UNIQUE(project_id,name COLLATE NOCASE));
CREATE TABLE IF NOT EXISTS project_members(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT '',skills_json TEXT NOT NULL,responsibilities_json TEXT NOT NULL,area_ids_json TEXT NOT NULL,component_ids_json TEXT NOT NULL,aliases_json TEXT NOT NULL,email TEXT,external_id TEXT,active INTEGER NOT NULL DEFAULT 1,UNIQUE(project_id,name COLLATE NOCASE));
CREATE TABLE IF NOT EXISTS assignment_rules(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL DEFAULT '',surface_id TEXT REFERENCES product_surfaces(id) ON DELETE SET NULL,component_id TEXT REFERENCES surface_components(id) ON DELETE SET NULL,area_id TEXT REFERENCES work_areas(id) ON DELETE SET NULL,task_type_id TEXT REFERENCES task_types(id) ON DELETE SET NULL,member_id TEXT NOT NULL REFERENCES project_members(id) ON DELETE RESTRICT,active INTEGER NOT NULL DEFAULT 1,position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS project_documents(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,filename TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,uploaded_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('uploaded','processing','extracting','indexing','ready','failed')),current_version INTEGER NOT NULL,current_version_id TEXT,extracted_text_metadata_json TEXT NOT NULL,chunk_count INTEGER NOT NULL DEFAULT 0,error TEXT,active INTEGER NOT NULL DEFAULT 1,UNIQUE(project_id,filename COLLATE NOCASE));
CREATE TABLE IF NOT EXISTS document_versions(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES project_documents(id) ON DELETE CASCADE,version INTEGER NOT NULL,file_path TEXT NOT NULL,size INTEGER NOT NULL,checksum TEXT NOT NULL,uploaded_at TEXT NOT NULL,extracted_text_metadata_json TEXT NOT NULL,UNIQUE(document_id,version));
CREATE TABLE IF NOT EXISTS document_chunks(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,document_id TEXT NOT NULL REFERENCES project_documents(id) ON DELETE CASCADE,version_id TEXT NOT NULL REFERENCES document_versions(id) ON DELETE CASCADE,filename TEXT NOT NULL,type TEXT NOT NULL,chunk_id TEXT NOT NULL,text TEXT NOT NULL,page_number INTEGER,row_number INTEGER,row_end_number INTEGER,source_metadata_json TEXT NOT NULL,PRIMARY KEY(version_id,chunk_id));
CREATE TABLE IF NOT EXISTS meetings(id TEXT PRIMARY KEY,input_type TEXT NOT NULL,title TEXT NOT NULL,meeting_type TEXT NOT NULL,context TEXT,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,project_snapshot_json TEXT,original_file_name TEXT NOT NULL,file_url TEXT NOT NULL,file_size INTEGER NOT NULL,duration REAL,status TEXT NOT NULL,stage TEXT,progress INTEGER NOT NULL,error TEXT,diagnostic TEXT,transcript TEXT,summary TEXT,topics_json TEXT NOT NULL,decisions_json TEXT NOT NULL,open_questions_json TEXT NOT NULL DEFAULT '[]',diarization_status TEXT DEFAULT 'not_started',diarization_error TEXT,speaker_count INTEGER,speaker_mappings_json TEXT DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transcript_segments(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,sequence INTEGER NOT NULL,start_ms INTEGER,end_ms INTEGER,speaker TEXT,text TEXT NOT NULL,speaker_id TEXT,speaker_confidence REAL,UNIQUE(meeting_id,sequence));
CREATE TABLE IF NOT EXISTS meeting_speaker_mappings(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,speaker_id TEXT NOT NULL,member_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(meeting_id,speaker_id));
CREATE TABLE IF NOT EXISTS task_candidates(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,intent TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,title TEXT NOT NULL,description TEXT NOT NULL,task_type_id TEXT REFERENCES task_types(id) ON DELETE SET NULL,type_label TEXT NOT NULL,product_surface_id TEXT REFERENCES product_surfaces(id) ON DELETE SET NULL,work_area_id TEXT REFERENCES work_areas(id) ON DELETE SET NULL,component_id TEXT REFERENCES surface_components(id) ON DELETE SET NULL,assigned_member_id TEXT REFERENCES project_members(id) ON DELETE SET NULL,priority TEXT NOT NULL,status TEXT NOT NULL,assignment_source TEXT NOT NULL,assignment_needs_review INTEGER NOT NULL,assignment_reason TEXT,rejection_reason TEXT,created_ticket_id TEXT,payload_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_document_refs(ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,document_version_id TEXT NOT NULL REFERENCES document_versions(id) ON DELETE RESTRICT,title TEXT NOT NULL,PRIMARY KEY(ticket_id,document_version_id));
CREATE TABLE IF NOT EXISTS processing_jobs(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL UNIQUE REFERENCES meetings(id) ON DELETE CASCADE,status TEXT NOT NULL,stage TEXT,progress INTEGER NOT NULL,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS created_tickets(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,source_task_id TEXT NOT NULL,meeting_id TEXT REFERENCES meetings(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL,context TEXT,expected_outcome TEXT,task_type TEXT,product_surface TEXT,component TEXT,work_area TEXT,priority TEXT,assignee TEXT,assignee_name TEXT,deadline TEXT,acceptance_criteria_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,source_evidence_json TEXT NOT NULL DEFAULT '[]',project_references_json TEXT NOT NULL DEFAULT '[]',external_key TEXT,provider TEXT NOT NULL DEFAULT 'internal');
CREATE INDEX IF NOT EXISTS idx_meetings_created ON meetings(created_at DESC);CREATE INDEX IF NOT EXISTS idx_tickets_meeting ON tickets(meeting_id);CREATE INDEX IF NOT EXISTS idx_documents_project ON project_documents(project_id,active);CREATE INDEX IF NOT EXISTS idx_segments_meeting ON transcript_segments(meeting_id,sequence);CREATE INDEX IF NOT EXISTS idx_speaker_mappings_meeting ON meeting_speaker_mappings(meeting_id);CREATE INDEX IF NOT EXISTS idx_document_chunks_project ON document_chunks(project_id,version_id);CREATE INDEX IF NOT EXISTS idx_document_chunks_source ON document_chunks(document_id,version_id,page_number,row_number);
CREATE UNIQUE INDEX IF NOT EXISTS idx_created_tickets_source_task ON created_tickets(source_task_id);CREATE INDEX IF NOT EXISTS idx_created_tickets_project ON created_tickets(project_id);CREATE INDEX IF NOT EXISTS idx_created_tickets_meeting ON created_tickets(meeting_id);
`;
